// Independent Metro experience. All operational information is illustrative.
let following=Boolean(saved.following),completed=false,returnFocus=null,closeTimer=null,crowdChoice='Seats available';
let reports=saved.reports||{},mapInstance=0;
const safe=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
profile=safe(profile);commutes=commutes.map(safe);
const ticketIcon=()=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h6v6H3zm12 0h6v6h-6zM3 15h6v6H3zm12 0h3v3h3v3h-6zm6 0v-3m-6 0h-3v6"/></svg>`;
const homeIcon=()=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10"/></svg>`;
function persist(){try{localStorage.setItem('metroConcept',JSON.stringify({profile,commutes,balance,remind,reported,large,following,reports}))}catch{}}
function setTab(t){state.tab=t;state.search=false;render();$('#panel').scrollTop=0;window.scrollTo({top:0,behavior:'instant'})}
function selectBus(i){state.selected=i;completed=false;render()}
function period(p){state.period=p;state.selected=0;state.arrival='approaching';state.trip=false;completed=false;render()}
function selected(){return routes[state.selected]}
function arrivalState(){return state.selected===0?state.arrival:'approaching'}
function serviceTime(){return time(selected())}
function endTime(){let m=serviceTime().match(/(\d+):(\d+) (AM|PM)/);let v=(Number(m[1])%12+(m[3]==='PM'?12:0))*60+Number(m[2])+54;return ((Math.floor(v/60)%12)||12)+':'+String(v%60).padStart(2,'0')+' '+(v%1440>=720?'PM':'AM')}
function statusText(){let a=arrivalState(),r=selected();return completed?'You’ve arrived':state.trip?'Next stop, '+(r.id==='CM05'?'Koswatta':'your next stop'):a==='passed'?'This bus has departed':a==='arrived'?'Your bus is here':`Arriving in ${r.mins} min`}
function badge(){let a=arrivalState();return completed?'Journey complete':state.trip?'On board':a==='passed'?'Stop passed':a==='arrived'?'At your stop':selected().delay?'Delayed '+selected().delay+' min':'On time'}
function rail(){let a=arrivalState();return `<div class="raillabels"><span>${completed||state.trip?'Departed':arrivalState()==='passed'?'Bus departed':'Bus approaching'}</span><span>${completed||state.trip?'Your destination':'Your boarding stop'}</span></div><div class="progressrail" style="--progress:${completed?'100%':state.trip?'43%':a==='passed'?'100%':a==='arrived'?'95%':'42%'};--progress-color:${a==='passed'?'#8a671e':'#27783c'}"><span class="rail-origin"></span><span class="rail-bus">${ic('bus')}</span><span class="rail-stop"></span></div>`}
function journeyCard(){let r=selected(),d=dir(r),a=arrivalState();return `<article class="journeycard" aria-label="Your current journey"><div class="journeybody"><div class="between"><span class="triptitle">${r.id} · Today ${state.period==='morning'?'AM':'PM'}</span><span class="pill ${a==='passed'||r.delay?'warn':''}">${badge()}</span></div><div class="journey-status counter">${statusText()}</div><p class="journey-sub">${completed?'Thanks for riding Metro.':state.trip?'Stay with your journey. We’ll show what comes next.':a==='passed'?'Your next option is a tap away.':a==='arrived'?'Check the destination. Have your boarding code ready.':'Leave now for a comfortable walk to the stop.'}</p>${rail()}<div class="journey-route"><div><b>${d.from}</b><span>${serviceTime()}</span></div>${ic('arrow')}<div class="to"><b>${d.to}</b><span>${endTime()} <span class="tiny">est.</span></span></div></div><div class="journeyfacts" style="margin-top:18px"><div class="journeyfact">${state.trip?'YOUR NEXT STOP':completed?'JOURNEY':'YOUR BOARDING STOP'}<b>${state.trip?(r.id==='CM05'?'Koswatta · 8 min':'Next stop · 8 min'):completed?'Completed · sample ride':d.from+' Junction'}</b></div><div class="journeyfact">${state.trip?'DESTINATION':completed?'WALLET BALANCE':'WALK TO STOP'}<b>${state.trip?d.to+' · ~46 min':completed?'Rs '+balance:'280 m · 4 min'}</b></div></div><div class="journey-actions"><button class="primary" onclick="${a==='passed'&&!state.trip?'nextBus()':completed?'newTrip()':'showQR()'}">${a==='passed'&&!state.trip?'Follow next bus':completed?'Plan another journey':ticketIcon()+' '+(state.trip?'Exit code':'Boarding code')}</button><button class="secondary" onclick="viewJourney()">View journey</button></div></div><div class="journeyfooter"><button onclick="${following?'toggleFollowing()':'followJourney()'}">${ic(following?'check':'bell')}${following?'Following journey':'Follow this journey'}</button><button onclick="viewMap()">${ic('pin')}View on map</button></div></article>`}
function home(){let d=dir(selected());return `<div class="homehero"><div class="between"><span class="eyebrow">YOUR EVERYDAY JOURNEY</span><button class="textbtn" onclick="previewStates()">Preview states ${ic('arrow')}</button></div><h1>${state.trip?'Enjoy the ride'+(profile?', '+profile:'')+'.':completed?'You’re here. Welcome.':'Good '+(state.period==='morning'?'morning':'evening')+(profile?', '+profile:'')+'.'}</h1><div class="hero-meta">${state.period==='morning'?'6:24 AM':'5:24 PM'} · ${state.trip?'On board':completed?'Journey complete':'Let’s get you there.'} <span style="float:right">Illustrative journey</span></div></div>${journeyCard()}<div class="directiontabs" role="group" aria-label="Commute direction"><button class="${state.period==='morning'?'selected':''}" onclick="period('morning')">Outbound <small>6:30 AM</small></button><button class="${state.period==='evening'?'selected':''}" onclick="period('evening')">Return <small>5:30 PM</small></button></div><button class="quicksearch" onclick="planJourney()">${ic('search')}<span><b>Where would you like to go?</b><small>Search stops, places or routes</small></span><span class="arrow">${ic('arrow')}</span></button><section class="section"><div class="sectionhead between"><h2>${state.trip?'Your bus, right now':'Nearby departures'}</h2><button class="textbtn" onclick="setTab('routes')">View all</button></div>${state.trip?onboardInfo():nearbyCard()}</section><div class="mobilemap floatmap"><div class="mapimage" role="img" aria-label="Illustrative schematic showing your selected Metro route">${mapSvg(selected())}</div><button onclick="viewMap()">${ic('pin')}Your journey on the map ${ic('arrow')}</button></div><section class="section"><div class="sectionhead between"><h2>Your everyday journeys</h2><button class="textbtn" onclick="saveCommute()">${commutes.length?'Edit':'Save'}</button></div><button class="walletpeek" onclick="${commutes.length?"setTab('saved')":"saveCommute()"}">${ic('star')}<span><strong>${commutes.length?commutes[0]:'Make this your usual'}</strong><small>Battaramulla ↔ Ekala · weekdays</small></span><span style="margin-left:auto">${ic('arrow')}</span></button></section><section class="section"><button class="walletpeek" onclick="setTab('wallet')">${ic('wallet')}<span><strong>Your LMT Go wallet</strong><small>Rs ${balance.toLocaleString()}.00 available · demo</small></span><span style="margin-left:auto">${ic('arrow')}</span></button></section><p class="bottomnote">Independent design concept. Times, stops, bus locations and fares are sample data. No operator connection.</p>`}
function nearbyCard(){let d=dir(selected());return `<div class="nearstop"><div class="nearstop-title">${ic('pin')}<b>${d.from} Junction</b></div><p class="tiny">Towards ${d.to} · 280 m from sample location</p>${(selected().id==='CM05'?routes.slice(0,2):[selected()]).filter(r=>!state.accessible||r.access).map(r=>{let i=routes.indexOf(r),a=i===0?state.arrival:'approaching';return `<button class="depart-row" onclick="selectBus(${i});viewJourney()"><span class="routebadge">${r.id}</span><span class="depart-info"><b>${dir(r).to}</b><small>${r.bus} · ${r.delay?'Delayed '+r.delay+' min':r.crowd}</small></span><span class="arrivalnum">${a==='passed'?'Left':a==='arrived'?'Here':r.mins}<small>${a==='approaching'?'min · sample GPS':'sample status'}</small></span></button>`}).join('')}<div class="metarow"><span>${ic('walk')}4 min walk</span><span>${ic('access')}Stop access unverified</span></div></div>`}
function onboardInfo(){let r=selected();return `<div class="nearstop"><div class="between"><b>${r.bus} · ${r.id}</b><span class="pill">${r.crowd}</span></div><p class="tiny" style="margin-top:9px">Operator sample · updated 1 min ago</p><div class="metarow"><span>${ic('access')}${r.access?'Low floor · ramp fitted':'Bus access unverified'}</span></div><p class="tiny">Wheelchair-space availability unverified</p>${reports[r.bus]?`<p class="tiny">Your passenger report: ${safe(reports[r.bus])}</p>`:''}<button class="textbtn" onclick="report()">How busy is your bus? ${ic('arrow')}</button></div>`}
function followJourney(){following=true;persist();render();toast('Journey pinned here. System notifications are not connected in this prototype.')}
function toggleFollowing(){following=false;persist();render();toast('Journey unpinned.')}
function nextBus(){state.selected=1;state.arrival='approaching';following=true;persist();closeModal();render();toast('Following MT 054. Sample arrival: 26 min.')}
function newTrip(){completed=false;state.trip=false;state.arrival='approaching';planJourney()}
function render(){let scroll=$('#panel').scrollTop;document.body.classList.toggle('large',large);$('#usericon').innerHTML=ic('user');$('#guestlabel').textContent=profile||'Guest';$('#nav').innerHTML=[['explore','home','Home'],['routes','explore','Explore'],['saved','bus','Journeys'],['wallet','wallet','Wallet'],['account','user','Account']].map(([t,i,l])=>`<button class="${state.tab===t?'active':''}" aria-current="${state.tab===t?'page':'false'}" onclick="setTab('${t}')">${i==='home'?homeIcon():ic(i)}${l}</button>`).join('');$('#panel').classList.toggle('homepanel',state.tab==='explore');$('#panel').innerHTML=state.tab==='explore'?home():state.tab==='routes'?routesPanel():state.tab==='saved'?savedPanel():state.tab==='wallet'?wallet():accountPanel();$('#panel').scrollTop=scroll;renderMap();$('#rideDock').className='rideDock';$('#rideDock').innerHTML=`<button class="dock-ticket" onclick="showQR()">${ticketIcon()}${state.trip?'Exit code':'Boarding code'}</button><button class="dock-journey" onclick="viewJourney()">${ic('bus')}<span><strong>${state.trip?'On board · '+selected().id:following?'Following · '+selected().id:'Your next bus · '+selected().id}</strong><small>${completed?'Journey complete':state.trip?'Next stop in 8 min':arrivalState()==='passed'?'Departed · view next bus':arrivalState()==='arrived'?'At your stop':selected().mins+' min · towards '+dir(selected()).to}</small></span>${ic('arrow')}</button>`}
function modal(title,body){clearTimeout(closeTimer);if(!$('#modalroot').innerHTML)returnFocus=document.activeElement;$('#modalroot').innerHTML=`<div class="modalback sheetback" onclick="if(event.target===this)closeModal()"><section class="sheet" role="dialog" aria-modal="true" aria-label="${title}" tabindex="-1"><div class="sheetgrip" aria-hidden="true"></div><div class="sheetheader"><h2>${title}</h2><button class="close" onclick="closeModal()" aria-label="Close dialog">${ic('close')}</button></div><div class="sheetcontent">${body}</div></section></div>`;document.querySelector('header').inert=true;$('.layout').inert=true;$('#rideDock').inert=true;document.body.style.overflow='hidden';installSheetGesture();requestAnimationFrame(()=>$('.sheetheader button')?.focus())}
function installSheetGesture(){let grip=$('.sheetgrip'),sheet=$('.sheet');let start=null;grip.onpointerdown=e=>{start=e.clientY;grip.setPointerCapture(e.pointerId);sheet.style.animation='none'};grip.onpointermove=e=>{if(start!==null)sheet.style.transform='translateY('+Math.max(0,e.clientY-start)+'px)'};grip.onpointerup=e=>{let distance=e.clientY-start;start=null;if(distance>75)closeModal();else{sheet.style.transition='transform .2s ease';sheet.style.transform='translateY(0)'}};grip.onpointercancel=()=>{start=null;sheet.style.transform=''}}
function closeModal(){let back=$('.sheetback');if(!back)return;let sheet=back.querySelector('.sheet');sheet.style.animation='';sheet.style.transform='';sheet.style.transition='';back.classList.add('closing');clearTimeout(closeTimer);closeTimer=setTimeout(()=>{$('#modalroot').innerHTML='';document.querySelector('header').inert=false;$('.layout').inert=false;$('#rideDock').inert=false;document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});returnFocus=null},matchMedia('(prefers-reduced-motion: reduce)').matches?0:180)}
document.addEventListener('keydown',e=>{let sheet=$('.sheet');if(!sheet||e.key!=='Tab')return;let controls=[...sheet.querySelectorAll('button,input,select,a[href],[tabindex="0"]')].filter(el=>!el.disabled&&!el.closest('[hidden]'));if(!controls.length)return;let first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
function viewJourney(){let r=selected(),d=dir(r),a=arrivalState();let stage=completed?4:state.trip?2:a==='passed'?1:0;const steps=[['Walk to your stop','4 min',`<p>Go to <b>${d.from} Junction</b>, towards ${d.to}. Leave now to allow 4 minutes to walk.</p><div class="card"><div class="row">${ic('pin')}<b>${d.from} Junction</b></div><span class="tiny">280 m · illustrative distance</span><div class="stopmap">${stopGraphic()}<span class="stopmaplabel">Sample boarding point</span></div><button class="textbtn" onclick="stopDetails()">Stop & accessibility details →</button></div>`],['Board your bus',serviceTime(),a==='passed'?`<p>This bus has already passed your stop.</p><button class="primary full" onclick="nextBus()">Follow next CM05 · 26 min</button>`:`<p>Look for <b>${r.bus}</b>, route ${r.id} to ${d.to}. Scan your boarding code on the bus.</p><button class="secondary full" onclick="showQR()">${ticketIcon()}Show boarding code</button>`],['Enjoy the ride','~54 min',`<p>${state.trip?'Next stop in 8 minutes. Your destination is about 46 minutes away.':'Follow the stops as you travel. Your destination stays visible throughout the ride.'}</p><div class="card"><b>${r.crowd}</b><span class="tiny">Operator sample · 1 min ago</span><button class="textbtn" style="display:block" onclick="report()">Share a crowding update →</button></div><button class="textbtn" onclick="activityPreview()">View Live Activity concept →</button>`],['Get off at '+d.to,endTime(),`<p>Have your exit code ready. Scan when leaving the bus to complete the journey.</p><button class="secondary full" onclick="showQR()">${ticketIcon()}${state.trip?'Show exit code':'View transit code'}</button>`]];modal('Your journey',`<div class="journeyhead"><div class="between"><span class="triptitle">${r.id} · ${r.bus}</span><span class="pill">${badge()}</span></div><h2>${d.from} → ${d.to}</h2><span class="tiny">${serviceTime()} – ${endTime()} estimated · sample data</span>${rail()}</div><div class="between"><h2 style="font-size:20px">${completed?'Journey complete':'A little guidance, all the way.'}</h2></div><p class="tiny" style="margin:9px 0 23px">${state.trip?'You’re on board. Your next step is highlighted.':'Walk, board, ride, arrive. Everything in order.'}</p><div class="schedulehead">Today’s journey · ${state.period==='morning'?'outbound':'return'}</div>${steps.map(([title,t,body],i)=>`<section class="travelstep ${i<stage?'done':i===stage?'current':''}"><span class="stepdot" aria-hidden="true"></span><button class="stepbutton" aria-expanded="${i===stage||i===stage+1}" aria-controls="step-${i}" onclick="toggleStep(this,'step-${i}')"><b>${title}</b><span class="row"><span class="tiny">${t}</span>${ic('arrow')}</span></button><div class="stepbody" id="step-${i}" ${i===stage||i===stage+1?'':'hidden'}>${body}</div></section>`).join('')}<div class="access-note">${ic('access')} ${r.access?'Low-floor bus with ramp fitted.':'Bus accessibility unverified.'} Stop access and wheelchair space are unverified. Check details before travelling.</div><button class="textbtn full" onclick="${following?'toggleFollowing();closeModal()':'followJourney();closeModal()'}">${following?'Stop following this journey':'Follow this journey'}</button>`)}
function toggleStep(button,id){let isOpen=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!isOpen));document.getElementById(id).hidden=isOpen}
function stopGraphic(){return `<svg viewBox="0 0 360 160" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><rect width="360" height="160" fill="#ececee"/><g fill="#dddde0"><rect x="20" y="15" width="74" height="40" rx="4"/><rect x="200" y="105" width="105" height="40" rx="4"/><rect x="250" y="10" width="95" height="45" rx="4"/></g><path d="M-10 85H370M140-20V180" stroke="white" stroke-width="22"/><path d="M140 35V85H220" stroke="#b51f2a" stroke-width="3" fill="none" stroke-dasharray="4 4"/><circle cx="140" cy="35" r="6" fill="#1b64b7" stroke="white" stroke-width="3"/><rect x="210" y="73" width="24" height="24" rx="6" fill="#111"/><use href="#i-bus" x="214" y="77" width="16" height="16" stroke="white" fill="none" stroke-width="1.7"/></svg>`}
function showQR(){let d=dir(selected());modal(state.trip?'Exit code':'Boarding code',`<div class="passes"><div class="between"><span><b>${selected().id} · Metro Transit</b><p class="tiny" style="margin:6px 0 0">${d.from} → ${d.to}</p></span><span class="pill neutral">DEMO</span></div><div class="pass-status">${ic(state.trip?'bus':'walk')} ${state.trip?'On board · scan when exiting':'Ready to board · scan on the bus'}</div><div class="passname">${profile||'Metro commuter'}</div><div class="democode"><div class="codeInner"><svg viewBox="0 0 160 160" aria-hidden="true"><g fill="none" stroke="#222" stroke-width="7"><path d="M12 43V12h31M117 12h31v31M148 117v31h-31M43 148H12v-31"/></g><g transform="translate(50 40)" stroke="#222" stroke-width="4" fill="none"><rect x="1" y="1" width="58" height="65" rx="12"/><path d="M1 30h58M15 67v11m30-11v11M16 45h1m26 0h1M19 12h22"/></g><text x="80" y="136" text-anchor="middle" font-size="14" font-family="Arial" letter-spacing="3" font-weight="bold" fill="#222">PREVIEW</text></svg></div></div><p class="pass-caption">Visual placeholder · not a scannable code or valid ticket</p><div class="passmeta"><span>Available balance<b>Rs ${balance.toLocaleString()}.00</b></span><span>Travel mode<b>Pay as you go</b></span></div><button class="primary full" onclick="simulateScan()">${ic('check')}Simulate ${state.trip?'exit':'boarding'} scan</button></div><p class="tiny" style="margin:17px 0">Prototype only. No fare is charged. A production code would be securely issued by the operator.</p><div class="row"><button class="secondary full" onclick="closeModal();setTab('wallet')">${ic('wallet')}Open wallet</button><button class="secondary full" onclick="viewJourney()">View journey</button></div>`)}
function simulateScan(){state.trip=!state.trip;completed=!state.trip;following=state.trip;state.tab='explore';state.arrival=state.trip?'arrived':'approaching';persist();closeModal();render();$('#panel').scrollTop=0;window.scrollTo({top:0,behavior:'smooth'});toast(state.trip?'Sample boarding confirmed. Your journey is now active.':'You’ve arrived. Sample exit confirmed. No charge was made.')}
function activityPreview(){let d=dir(selected());modal('Live Activity · visual concept',`<p class="sub" style="margin:0 0 18px">The essential journey update, imagined on your lock screen. This is an in-app visual only.</p><div class="activitypreview"><div class="activitydate">Today · Metro commute</div><div class="activity-clock">${state.period==='morning'?'6:24':'17:24'}</div><div class="activitycard"><div class="between"><b>${selected().id} · ${selected().bus}</b><span class="live">${badge()}</span></div><h3>${state.trip?'Next stop in 8 min':arrivalState()==='passed'?'Bus has departed':arrivalState()==='arrived'?'Your bus is here':selected().mins+' min to your stop'}</h3><p class="tiny">${d.from} → ${d.to}</p>${rail()}<p class="tiny" style="margin-top:12px">${state.trip?'On board · get off at '+d.to:'Board at '+d.from+' Junction'}</p></div><p style="text-align:center;font-size:10px;color:#aaa;margin:20px 0 5px">LOCK SCREEN CONCEPT · SAMPLE DATA</p></div><div class="access-note">Native Live Activities and system notifications require a supported native implementation. This website does not activate them.</div><button class="primary full" style="margin-top:20px" onclick="viewJourney()">Back to your journey</button>`)}
function planJourney(){let d=dir(selected());modal('Where are you going?',`<p class="sub">Find a bus, then follow the whole journey.</p><form onsubmit="event.preventDefault();searchTrip()"><div class="searchbox"><label class="row">${ic('locate')}<span class="sr-only">Starting point</span><input id="from" aria-label="Starting point" value="${d.from}"><button type="button" aria-label="Use sample location" onclick="locate()">${ic('locate')}</button></label><label class="row">${ic('pin')}<span class="sr-only">Destination</span><input id="to" aria-label="Destination" placeholder="Where to?" list="destinations"><datalist id="destinations"><option value="Ekala"><option value="Battaramulla"></datalist></label></div><button type="button" class="chip ${state.accessible?'selected':''}" aria-pressed="${state.accessible}" onclick="state.accessible=!state.accessible;this.classList.toggle('selected');this.setAttribute('aria-pressed',state.accessible)">${ic('access')}Prefer step-free buses</button><button class="primary full" style="margin-top:20px">Find buses ${ic('arrow')}</button></form><p class="tiny" style="margin-top:18px">Connected sample journey: Battaramulla ↔ Ekala. Explore shows all sample Metro routes.</p>`)}
function searchTrip(){let f=$('#from').value.trim().toLowerCase(),t=$('#to').value.trim().toLowerCase();if(!f||!t){toast('Enter your starting point and destination.');return}if(!(f.includes('battaramulla')&&t.includes('ekala')||f.includes('ekala')&&t.includes('battaramulla'))){toast('Try Battaramulla ↔ Ekala for this sample journey. Other routes are in Explore.');return}state.period=f.includes('ekala')?'evening':'morning';state.selected=0;state.search=true;state.trip=false;completed=false;journeyResults()}
function journeyResults(){let d=dir(routes[0]);modal('Your bus options',`<div class="screen-heading"><span class="eyebrow">DIRECT JOURNEY · ${state.period==='morning'?'OUTBOUND':'RETURN'}</span><h1 style="font-size:25px">${d.from} → ${d.to}</h1><p class="sub">4 min walk · about 54 min on the bus</p></div>${routes.slice(0,2).map(r=>`<div class="card"><div class="between"><b>${time(r)}</b><span class="pill ${r.delay?'warn':''}">${r.delay?'Delayed '+r.delay+' min':'On time'}</span></div><div class="journey-route"><span><b>${d.from}</b>Boarding stop</span>${ic('arrow')}<span class="to"><b>${d.to}</b>Destination</span></div><div class="metarow"><span>${ic('people')}${r.crowd}</span><span>${ic('access')}Low-floor bus</span></div><button class="primary full" style="margin-top:16px" onclick="chooseJourney(${routes.indexOf(r)})">Follow ${r.bus} · ${r.mins} min</button></div>`).join('')}<div class="access-note">Stop access and wheelchair-space availability remain unverified. Arrival information is illustrative.</div>`)}
function chooseJourney(i){state.selected=i;following=true;state.tab='explore';state.arrival='approaching';persist();closeModal();render();$('#panel').scrollTop=0;window.scrollTo({top:0,behavior:'smooth'});toast('Journey selected. Your next steps are on Home.')}
function routesPanel(){return `<div class="screen-heading"><span class="eyebrow">THE METRO NETWORK</span><h1>Explore your way.</h1><p class="sub">Routes, stops and buses. Together.</p></div><button class="quicksearch" onclick="planJourney()">${ic('search')}<span><b>Plan a journey</b><small>Choose where you’re going</small></span><span class="arrow">${ic('arrow')}</span></button><div class="mobilemap floatmap"><div class="mapimage" role="img" aria-label="Sample network schematic">${mapSvg(selected())}</div><button onclick="viewMap()">Open map & bus locations ${ic('arrow')}</button></div><div class="searchbox row" style="margin-top:20px">${ic('search')}<input placeholder="Route number or place" aria-label="Search routes" oninput="filterRoutes(this.value)"></div><div class="between"><button class="chip ${state.accessible?'selected':''}" aria-pressed="${state.accessible}" onclick="state.accessible=!state.accessible;render()">${ic('access')}Step-free buses</button><button class="textbtn" onclick="period(state.period==='morning'?'evening':'morning')">Reverse direction</button></div><div class="section" id="routeList">${routeList('')}</div><p class="bottomnote">All route times and locations are sample data. Stop access is unverified.</p>`}
function routeCard(r,i){let d=dir(r),a=i===0?state.arrival:'approaching';return `<button class="card routecard ${i===state.selected?'selected':''}" onclick="selectBus(${i});viewJourney()" aria-label="${r.id}, towards ${d.to}, ${a==='passed'?'departed':a==='arrived'?'at stop':r.mins+' minutes'}"><div class="between"><span class="row"><span class="routebadge">${r.id}</span><b>Towards ${d.to}</b></span><span class="arrivalnum">${a==='passed'?'Left':a==='arrived'?'Here':r.mins}<small>${a==='approaching'?'min':''}</small></span></div><p class="tiny" style="margin:9px 0 0">${r.from} · ${r.via}</p><div class="metarow"><span>${ic('people')}${r.crowd}</span><span>${ic('access')}${r.access?'Low-floor bus':'Access unverified'}</span></div></button>`}
function savedPanel(){return `<div class="screen-heading"><span class="eyebrow">YOUR JOURNEYS</span><h1>Your everyday, simplified.</h1><p class="sub">Outbound and return, kept together.</p></div>${following||state.trip?`<div class="card section"><span class="eyebrow">${state.trip?'ACTIVE RIDE':'FOLLOWING NOW'}</span><h2 style="margin:13px 0">${routeTitle(selected())}</h2><p class="sub">${statusText()}</p><button class="primary full" style="margin-top:15px" onclick="viewJourney()">View journey</button></div>`:''}<section class="section"><div class="sectionhead between"><h2>Saved commutes</h2><button class="textbtn" onclick="saveCommute()">Add commute</button></div>${commutes.length?commutes.map((c,i)=>`<div class="card"><div class="between"><h2>${c}</h2><button class="close" aria-label="Remove saved commute" onclick="commutes.splice(${i},1);persist();render()">${ic('close')}</button></div><p class="tiny">Weekdays · CM05</p><button class="depart-row" onclick="period('morning');state.tab='explore';following=true;persist();render()"><span class="depart-info"><b>Battaramulla → Ekala</b><small>Outbound · 6:30 AM</small></span>${ic('arrow')}</button><button class="depart-row" onclick="period('evening');state.tab='explore';following=true;persist();render()"><span class="depart-info"><b>Ekala → Battaramulla</b><small>Return · 5:30 PM</small></span>${ic('arrow')}</button></div>`).join(''):`<div class="card empty"><h2 style="margin-bottom:10px">Your usual bus, one tap away.</h2><p class="sub">Save both directions of a commute, without an account.</p><button class="primary" style="margin-top:18px" onclick="saveCommute()">Save your commute</button></div>`}</section><p class="bottomnote">Saved on this browser. Operator account sync is not connected.</p>`}
function commitCommute(){commutes=[safe($('#name').value.trim()||'Work commute')];persist();closeModal();render();toast('Both directions saved in Journeys.')}
function report(){crowdChoice='Seats available';let r=selected();modal('How busy is your bus?',`<p class="sub" style="margin-bottom:20px">${r.bus} · Towards ${dir(r).to}</p><div class="report-choice" role="group" aria-label="Crowding report">${['Seats available','Standing room','Very crowded'].map((c,i)=>`<button class="${i===0?'selected':''}" aria-pressed="${i===0}" onclick="crowdChoice='${c}';document.querySelectorAll('.report-choice button').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});this.classList.add('selected');this.setAttribute('aria-pressed','true')">${ic('people')}${c}</button>`).join('')}</div><label class="row" style="font-weight:400;margin:22px 0"><input type="checkbox" id="onbus" ${state.trip?'checked':''} style="width:20px;min-height:20px;margin:0"> I’m on this bus now</label><button class="primary full" onclick="sendReport()">Share sample update</button><p class="tiny" style="margin-top:17px">Passenger updates are separate from operator data. This demo saves your report locally and sends nothing.</p>`)}
function sendReport(){if(!$('#onbus').checked){toast('Please confirm you’re on the bus before reporting.');return}reports[selected().bus]=crowdChoice;persist();closeModal();render();toast('Your sample passenger report was added.')}
function stopDetails(){let r=selected(),d=dir(r);modal('Your boarding stop',`<div class="stopmap" style="height:180px;margin:0 0 20px">${stopGraphic()}<span class="stopmaplabel">Illustrative stop location</span></div><h2 style="font-size:23px">${d.from} Junction</h2><p class="sub" style="margin:10px 0">Towards ${d.to} · 280 m · 4 min walk</p><div class="card"><b>Check before you board</b><p class="sub" style="margin-top:7px">Look for route ${r.id}, bus ${r.bus}, with ${d.to} on the destination display.</p></div><div class="access-note"><b>Stop accessibility unverified</b><br>Kerb height, pavement access and ramp boarding space need confirmation. ${r.access?'The sample bus is marked low-floor with a ramp.':'Bus accessibility is also unverified.'} Wheelchair space is unverified.</div><button class="primary full" style="margin-top:20px" onclick="viewJourney()">Back to journey</button><p class="tiny" style="margin-top:17px">Walking directions require a connected map provider. This schematic cannot guide navigation.</p>`)}
function mapSvg(r){const mapId=++mapInstance;return schematicMapSvg(r).replaceAll('#e9ede5','#ececee').replaceAll('#f5f7f1','#f5f5f6').replaceAll('#d9e0d5','#e1e1e3').replaceAll('#d7e2cb','#e0e1df').replaceAll('#b6d3ce','#ced7de').replaceAll('#d3d8ca','#dadade').replaceAll('#66776b','#77777c').replaceAll('#253c33','#333339').replaceAll('#fdfdf9','#fdfdfd').replaceAll(r.color,'#b51f2a').replaceAll('id="shadow"','id="shadow-'+mapId+'"').replaceAll('url(#shadow)','url(#shadow-'+mapId+')').replaceAll('id="grid"','id="grid-'+mapId+'"').replaceAll('url(#grid)','url(#grid-'+mapId+')')}
function renderMap(){let r=selected(),d=dir(r);$('#maparea').innerHTML=`<div class="map" role="img" aria-label="Illustrative schematic for ${r.id}. Not for navigation.">${mapSvg(r)}</div><div class="maptop"><div class="map-switch" role="group" aria-label="Map display"><button class="${state.view==='map'?'active':''}" onclick="state.view='map';renderMap()">Map</button><button class="${state.view==='line'?'active':''}" onclick="state.view='line';renderMap()">Route line</button><button class="${state.view==='list'?'active':''}" onclick="state.view='list';renderMap()">Buses</button></div><span class="mapkey"><span class="dot" style="color:#26743b"></span>Sample positions · just updated</span></div>${state.view==='list'?`<div class="listmode"><h2>Buses on ${r.id}</h2><p class="sub" style="margin:10px 0 20px">Towards ${d.to} · illustrative arrivals</p>${(r.id==='CM05'?routes.slice(0,2):[r]).map(x=>routeCard(x,routes.indexOf(x))).join('')}<button class="secondary full" onclick="state.view='map';renderMap()">Back to map</button></div>`:`<div class="mapbottom"><div class="detail"><div class="between"><b>${r.id} · ${r.bus}</b><span class="pill ${arrivalState()==='passed'?'warn':''}">${badge()}</span></div><h2>${statusText()}</h2><p class="sub" style="font-size:12px">${d.from} → ${d.to}</p>${rail()}<div class="journey-route" style="margin-top:0"><span><b style="font-size:15px">${serviceTime()}</b>${d.from}</span><span class="to"><b style="font-size:15px">${endTime()}</b>${d.to} · estimated</span></div><div class="metarow" style="margin:18px 0"><span>${ic('people')}${r.crowd}</span><span>${ic('access')}${r.access?'Low-floor bus':'Access unverified'}</span></div>${reports[r.bus]?`<p class="tiny">Your passenger report: ${safe(reports[r.bus])}</p>`:''}<div class="row"><button class="primary full" onclick="viewJourney()">View journey ${ic('arrow')}</button><button class="secondary" onclick="stopDetails()">Your stop</button></div><button class="textbtn full" onclick="activityPreview()">Preview Live Activity</button></div><div class="controls"><button aria-label="Zoom in" onclick="state.zoom=Math.min(1.6,state.zoom+.2);renderMap()">+</button><button aria-label="Zoom out" onclick="state.zoom=Math.max(.8,state.zoom-.2);renderMap()">−</button><button aria-label="Centre map" onclick="state.zoom=1;renderMap()">${ic('locate')}</button></div></div>`}<span class="map-note">Schematic · sample positions · not for navigation</span>`}
function viewMap(){let r=selected();modal('Your route & bus',`<div class="sheet-map" role="img" aria-label="Illustrative Metro route schematic">${mapSvg(r)}</div><div class="map-switch" style="width:max-content;margin-bottom:20px"><button class="${state.view==='map'?'active':''}" onclick="state.view='map';viewMap()">Map</button><button class="${state.view==='line'?'active':''}" onclick="state.view='line';viewMap()">Route line</button></div><div class="between"><b>${r.id} · ${r.bus}</b><span class="pill">${badge()}</span></div><h2 style="font-size:25px;margin:14px 0 5px">${statusText()}</h2><p class="sub">Towards ${dir(r).to}</p>${rail()}<div class="timeline"><span class="station">Previous stop<br><b>Passed</b></span><span class="station current">${dir(r).from}<br><b>${arrivalState()==='passed'?'Departed':arrivalState()==='arrived'?'Here':r.mins+' min'}</b></span><span class="station">Next stop<br><b>${r.mins+8} min</b></span><span class="station">${dir(r).to}<br><b>~54 min</b></span></div><div class="metarow"><span>${ic('people')}${r.crowd}</span><span>${ic('access')}${r.access?'Low-floor bus':'Bus access unverified'}</span></div><p class="tiny" style="margin:15px 0">Schematic map and times are illustrative. Stop access and wheelchair space are unverified.</p><button class="primary full" onclick="viewJourney()">View journey ${ic('arrow')}</button>`)}
const baseAccount=legacyAccountPanel;
function accountPanel(){return baseAccount().replace('<button class="textbtn" onclick="aboutDialog()">',`<section class="section"><h2>Explore the concept</h2><button class="depart-row" onclick="activityPreview()"><span class="depart-info"><b>Live Activity preview</b><small>See essential updates at a glance</small></span>${ic('arrow')}</button><button class="depart-row" onclick="previewStates()"><span class="depart-info"><b>Journey states</b><small>Try arrival, delays and an active ride</small></span>${ic('arrow')}</button></section><button class="textbtn" onclick="aboutDialog()">`)}
function previewStates(){modal('Preview journey states',`<p class="sub" style="margin:0 0 20px">Try the interface at different moments in a sample commute. No real journey is started.</p><div class="state-controls">${[['approaching','Bus approaching'],['arrived','Bus at stop'],['delayed','Bus delayed'],['passed','Missed bus'],['onboard','On board'],['complete','Journey complete']].map(([v,l])=>`<button onclick="applyPreview('${v}')">${l} ${ic('arrow')}</button>`).join('')}</div><p class="tiny" style="margin-top:20px">The Outbound / Return tabs on Home switch between the 6:30 AM and 5:30 PM commute examples.</p>`)}
function applyPreview(v){state.selected=v==='delayed'?1:0;state.arrival=['approaching','arrived','passed'].includes(v)?v:'approaching';state.trip=v==='onboard';completed=v==='complete';following=true;state.tab='explore';closeModal();render();$('#panel').scrollTop=0;window.scrollTo({top:0,behavior:'smooth'})}
render();
